import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(max(old_limit, len(raw_csv)))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=";"))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])

    existing = set(columns)
    while len(columns) < width:
        base = "column_" + str(len(columns) + 1)
        name = base
        suffix = 2
        while name in existing:
            name = base + "_" + str(suffix)
            suffix += 1
        columns.append(name)
        existing.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
